#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>

int main() {
  int fd = open("my_file.txt", O_RDONLY);
  if (fd == -1) {
    perror("open failed");
    return 1;
  }

  char buffer[1024];
  ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
  if (bytes_read == -1) {
    perror("read failed");
    close(fd);
    return 1;
  }

  printf("Read %zd bytes: %s\n", bytes_read, buffer);
  close(fd);
  return 0;
}
